args.command:
$paths = @("C:\Program Files", "C:\Program Files (x86)", "C:\ProgramData", "$env:USERPROFILE\AppData")
foreach ($path in $paths) {
    Write-Host "--- Scanning: $path ---"
    Get-ChildItem -Path $path -ErrorAction SilentlyContinue | 
    ForEach-Object {
        $subfolders = $_.FullName
        $size = (Get-ChildItem $subfolders -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        if ($size -ne $null) {
            [PSCustomObject]@{
                Path = $_.Name
                SizeGB = [math]::Round($size / 1GB, 2)
            }
        }
    } | Sort-Object SizeGB -Descending | Select-Object -First 5 | Format-Table -AutoSize
}

$path = "$env:USERPROFILE\AppData\Local"
Write-Host "--- Scanning: $path ---"
Get-ChildItem -Path $path -ErrorAction SilentlyContinue | 
ForEach-Object {
    $subfolders = $_.FullName
    $size = (Get-ChildItem $subfolders -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
    if ($size -ne $null) {
        [PSCustomObject]@{
            Name = $_.Name
            SizeGB = [math]::Round($size / 1GB, 2)
        }
    }
} | Sort-Object SizeGB -Descending | Select-Object -First 10 | Format-Table -AutoSize

# Checking for known non-programming / non-essential targets
$targets = @(
    "C:\Program Files\EA Games",
    "C:\Program Files\Electronic Arts",
    "C:\Program Files (x86)\Steam",
    "$env:USERPROFILE\AppData\Local\Steam",
    "$env:USERPROFILE\AppData\Local\Mozilla\Firefox\Profiles",
    "C:\Windows\SoftwareDistribution\Download",
    "C:\Windows\Temp",
    "$env:USERPROFILE\AppData\Local\Temp"
)

foreach ($t in $targets) {
    if (Test-Path $t) {
        $size = (Get-ChildItem $t -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        Write-Host "$t : $([math]::Round($size / 1GB, 2)) GB"
    }
}

# Check User Media folders
Write-Host "--- User Media ---"
$media = @("Videos", "Music", "Pictures")
foreach ($m in $media) {
    $path = Join-Path $env:USERPROFILE $m
    if (Test-Path $path) {
        $size = (Get-ChildItem $path -Recurse -File -ErrorAction SilentlyContinue | Measure-Object -Property Length -Sum).Sum
        Write-Host "$path : $([math]::Round($size / 1GB, 2)) GB"
    }
}

$targets = @(
    "C:\Program Files\EA Games",
    "C:\Program Files\Electronic Arts",
    "C:\Program Files (x86)\Steam",
    "$env:USERPROFILE\AppData\Local\Steam",
    "$env:USERPROFILE\AppData\Local\Mozilla\Firefox\Profiles",
    "C:\Windows\Temp\*",
    "$env:USERPROFILE\AppData\Local\Temp\*",
    "$env:USERPROFILE\Videos\*"
)

foreach ($t in $targets) {
    if (Test-Path $t) {
        Write-Host "Deleting: $t"
        Remove-Item -Path $t -Recurse -Force -ErrorAction SilentlyContinue
    }
}
